              {S.cur === id && k < S.k && <circle cx={x + 24} cy={y + 26} r={28} fill="none" stroke={C.ink} strokeWidth={2.5} />}
              {mk && mk.mode !== "none" && kv !== null && k < mk.shown && <text x={x + 24} y={y + (hg ? 74 : 76)} textAnchor="middle" fontSize={T.micro} fontWeight={700} fill={PG_AMBER}>{mk.mode === "sum" ? kv * (k + 1) : kv}</text>}
